// Biography page — loads data/biography.json (generated by the
// knowledge-base repo's _tools/cv_build.py; do not hand-edit the JSON)
// and renders the intro prose plus each CV section as a table.

async function initBiographyPage() {
    const container = document.getElementById('biography-body');
    if (!container) return;

    try {
        const response = await fetch('data/biography.json');
        const data = await response.json();
        container.innerHTML = renderIntro(data.intro_html) + renderSections(data.sections);
    } catch (err) {
        console.error('Error loading biography data:', err);
        container.innerHTML = '<p class="text-muted">Unable to load biography.</p>';
    }
}

function renderIntro(paragraphs) {
    return (paragraphs || []).join('\n');
}

function renderSections(sections) {
    return (sections || []).map(section => `
<h2>${section.heading}</h2>
<table class="bio-table">
${section.rows.map(renderRow).join('')}
</table>`).join('');
}

function renderRow(row) {
    return `    <tr>
        <td class="bio-years">${row.years}</td>
        <td class="bio-details">${row.detail_html}</td>
    </tr>
`;
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initBiographyPage);
} else {
    initBiographyPage();
}
